from collections import Counter
def solve(inp):
    h,w=len(inp),len(inp[0])
    allc=Counter(v for r in inp for v in r)
    # find separator line: full row or column of one color unique to it
    for j in range(w):
        c=inp[0][j]
        if all(r[j]==c for r in inp) and all(inp[i][j2]!=c for i in range(h) for j2 in range(w) if j2!=j):
            L=[r[:j] for r in inp]; R=[r[j+1:] for r in inp]; break
    else:
        for i in range(h):
            c=inp[i][0]
            if all(v==c for v in inp[i]) and all(inp[i2][j]!=c for i2 in range(h) if i2!=i for j in range(w)):
                L=inp[:i]; R=inp[i+1:]; break
    bgL=Counter(v for r in L for v in r if v).most_common(1)[0][0]
    bgR=Counter(v for r in R for v in r if v).most_common(1)[0][0]
    return [[2 if a==bgL and b==bgR else 0 for a,b in zip(ra,rb)] for ra,rb in zip(L,R)]
